local TuningPinMaker = {}
local PRODUCTS = {
    iron_tuningpin = { name = "Železni uglaševalni čivek", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni uglaševalni čivek za glasbila." },
    bronze_tuningpin = { name = "Bronast uglaševalni čivek", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast uglaševalni čivek za fino glasbo." },
    silver_tuningpin = { name = "Srebrn uglaševalni čivek", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn uglaševalni čivek za plemiške glasbenike." },
    gilded_tuningpin = { name = "Pozlačen uglaševalni čivek", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen uglaševalni čivek za dvorne glasbenike." },
    jewel_set_tuningpin = { name = "Draguljast uglaševalni čivek", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast uglaševalni čivek za kraljevske glasbenike." },
    royal_sovereign_tuningpin = { name = "Kraljevski suveren uglaševalni čivek", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren uglaševalni čivek z biseri za krono." },
}
local BUILDINGS = {
    tuningpin_workshop = { name = "Tuningpin delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    tuningpin_house = { name = "Tuningpin hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_tuningpin_atelier = { name = "Mojstrski tuningpin atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_tuningpin_palace = { name = "Suverena tuningpin palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
TuningPinMaker.ironStock = 16; TuningPinMaker.bronzeStock = 14; TuningPinMaker.woodStock = 10; TuningPinMaker.leatherStock = 8; TuningPinMaker.silverStock = 8; TuningPinMaker.goldStock = 6; TuningPinMaker.jewelStock = 4; TuningPinMaker.pearlStock = 4
TuningPinMaker.productStock = {}; TuningPinMaker.buildings = {}; TuningPinMaker.maker = nil; TuningPinMaker.activeMaking = {}; TuningPinMaker.totalProducts = 0; TuningPinMaker.dayTimer = 0
function TuningPinMaker.init() TuningPinMaker.ironStock=16; TuningPinMaker.bronzeStock=14; TuningPinMaker.woodStock=10; TuningPinMaker.leatherStock=8; TuningPinMaker.silverStock=8; TuningPinMaker.goldStock=6; TuningPinMaker.jewelStock=4; TuningPinMaker.pearlStock=4; TuningPinMaker.productStock={}; TuningPinMaker.buildings={}; TuningPinMaker.maker=nil; TuningPinMaker.activeMaking={}; TuningPinMaker.totalProducts=0; TuningPinMaker.dayTimer=0; print("[TuningPinMaker] Royal Tuning Pin Maker System initialized (6 products, 4 buildings)") end
function TuningPinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TuningPinMaker.maker={name=n or ("Čivkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čivkar najet: %s (spretnost: %d)",TuningPinMaker.maker.name,s),"success") end; return true end
function TuningPinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TuningPinMaker.build(id) local ok,e=TuningPinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TuningPinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TuningPinMaker.getQualityBonus() local b=0; for _,bd in ipairs(TuningPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TuningPinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TuningPinMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TuningPinMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TuningPinMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TuningPinMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TuningPinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TuningPinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TuningPinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TuningPinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TuningPinMaker.buildings==0 then return false,"Potrebna civkarska delavnica" end; if not TuningPinMaker.maker then return false,"Potreben civkar" end; return true end
function TuningPinMaker.make(pt,qty) qty=qty or 1; local ok,e=TuningPinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TuningPinMaker.ironStock=TuningPinMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TuningPinMaker.bronzeStock=TuningPinMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TuningPinMaker.woodStock=TuningPinMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TuningPinMaker.leatherStock=TuningPinMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TuningPinMaker.silverStock=TuningPinMaker.silverStock-d.silverCost*qty end; if d.goldCost then TuningPinMaker.goldStock=TuningPinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TuningPinMaker.jewelStock=TuningPinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TuningPinMaker.pearlStock=TuningPinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TuningPinMaker.maker then t=math.max(1,t-math.floor(TuningPinMaker.maker.skill/13)) end; table.insert(TuningPinMaker.activeMaking,{id="tuningpin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TuningPinMaker.completeMaking(m) local q=1.0+(TuningPinMaker.getQualityBonus()/100); if TuningPinMaker.maker then q=q+(TuningPinMaker.maker.skill/140) end; q=math.min(2.5,q); TuningPinMaker.productStock[m.productType]=(TuningPinMaker.productStock[m.productType] or 0)+m.quantity; TuningPinMaker.totalProducts=TuningPinMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TuningPinMaker.maker then TuningPinMaker.maker.itemsMade=TuningPinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TuningPinMaker.maker.skill=math.min(100,TuningPinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čivek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tuningpin.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TuningPinMaker.update(dt) if not _G.state then return end; TuningPinMaker.dayTimer=TuningPinMaker.dayTimer+dt; if TuningPinMaker.dayTimer>=30 then TuningPinMaker.dayTimer=0; for i=#TuningPinMaker.activeMaking,1,-1 do local m=TuningPinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TuningPinMaker.completeMaking(m); table.remove(TuningPinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TuningPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TuningPinMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TuningPinMaker.getStats() return {ironStock=TuningPinMaker.ironStock,bronzeStock=TuningPinMaker.bronzeStock,woodStock=TuningPinMaker.woodStock,leatherStock=TuningPinMaker.leatherStock,silverStock=TuningPinMaker.silverStock,goldStock=TuningPinMaker.goldStock,jewelStock=TuningPinMaker.jewelStock,pearlStock=TuningPinMaker.pearlStock,productStock=TuningPinMaker.productStock,numBuildings=#TuningPinMaker.buildings,hasMaker=TuningPinMaker.maker~=nil,makerName=TuningPinMaker.maker and TuningPinMaker.maker.name or "—",makerSkill=TuningPinMaker.maker and TuningPinMaker.maker.skill or 0,activeMaking=#TuningPinMaker.activeMaking,totalProducts=TuningPinMaker.totalProducts} end
return TuningPinMaker
